<?php
namespace App\Http\Controllers;use App\Models\{Employee,Payslip,Project};use App\Services\PayslipService;use Barryvdh\DomPDF\Facade\Pdf;use Illuminate\Http\Request;class PayslipController extends Controller{function index(){return view('payslips.index',['items'=>Payslip::with('employee','project')->latest()->paginate(30),'employees'=>Employee::all(),'projects'=>Project::all()]);}function generate(Request $r,PayslipService $s){$d=$r->validate(['employee_id'=>'nullable','project_id'=>'nullable','month'=>'required|integer','year'=>'required|integer']);$emps=Employee::when($d['employee_id']??null,fn($q,$v)=>$q->whereKey($v))->when($d['project_id']??null,fn($q,$v)=>$q->where('current_project_id',$v))->get();foreach($emps as $e)$s->generate($e,$d['project_id']??$e->current_project_id,$d['month'],$d['year'],auth()->id());return back()->with('success','Payslips generated');}function show(Payslip $payslip){$payslip->load('employee','project');return view('payslips.show',compact('payslip'));}function finalize(Payslip $payslip,PayslipService $s){$s->finalize($payslip);return back();}function pdf(Payslip $payslip){return Pdf::loadView('payslips.pdf',compact('payslip'))->download('payslip-'.$payslip->id.'.pdf');}}
